-- Kosan Aman: dump MySQL/MariaDB (impor lewat phpMyAdmin > Import)
-- Isi kolom `payload` = data TERENKRIPSI (AES-256-GCM + RSA-OAEP), bukan teks asli.
-- Dibuat dari database/kosan.db pada 2026-11-11 15:07
-- Catatan: aplikasi PHP tetap membaca SQLite (database/kosan.db); berkas ini untuk dilihat/dikumpulkan.

SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS `kosan_aman` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `kosan_aman`;

DROP TABLE IF EXISTS `login_fail`, `pembayaran`, `kamar`, `penghuni`, `booking`, `meta`;

CREATE TABLE `meta` (
  `key`   VARCHAR(64) NOT NULL PRIMARY KEY,
  `value` TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Booking calon penghuni dari landing page (terenkripsi)
CREATE TABLE `booking` (
  `id`         INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `payload`    TEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Data penghuni: nama, HP, NIK KTP, kontak darurat, kamar (terenkripsi)
CREATE TABLE `penghuni` (
  `id`         INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `payload`    TEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Unit kamar: nomor, tipe, lantai, catatan (terenkripsi)
CREATE TABLE `kamar` (
  `id`         INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `payload`    TEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Pembayaran sewa bulanan: penghuni, periode, jumlah, metode (terenkripsi)
CREATE TABLE `pembayaran` (
  `id`         INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `payload`    TEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Pembatasan percobaan login gagal (anti brute-force)
CREATE TABLE `login_fail` (
  `ip`      VARCHAR(64) NOT NULL PRIMARY KEY,
  `n`       INT NOT NULL,
  `started` INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

